import{z as o,x as s,o as e,c as n,q as r,j as A,D as a,d as t,s as i,S as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"越权行为的度量","description":"","frontmatter":{"title":"越权行为的度量","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aeval-overrefusal-metric.md","filePath":"llm/aeval-overrefusal-metric.md","lastUpdated":1791063341000}'),d={name:"llm/aeval-overrefusal-metric.md"};function m(p,E,h,_,D,F){const l=s("Mermaid");return e(),n("div",null,[E[2]||(E[2]=r('<h1 id="越权行为的度量" tabindex="-1">越权行为的度量 <a class="header-anchor" href="#越权行为的度量" aria-label="Permalink to &quot;越权行为的度量&quot;">​</a></h1><div class="epigraph"><p>过度拒绝是安全工作的影子账：主表上的 ASR 每降一点，都要在对照集上量一遍影子有没有变长——影子不进表，工作点就会悄悄滑向「全部拒绝」。</p><footer>—— 据 XSTest 一类过拒绝探针的构造口径与 Bai et al., 2022 的有用/无害张力整理</footer></div><p><a href="/llm/aeval-redteam-engineering">上一课</a>把主动找失败收成自动化与人工两条产线和一个版本化的回归漏斗。红队找的是「该拒没拒」；镜像失败「不该拒却拒」没有攻击者替你发现——受害用户只会默默离开。机制侧，<a href="/llm/over-refusal">过度拒绝</a>写过捷径来源与叠层相乘；本课把度量本身钉成协议：探针怎么构造、判分怎么三分、数字怎么分域、工作点怎么门禁。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><span class="marginnote">术语翻译：越权拒绝（over-refusal）就是「政策允许你答、你却拒了」的误伤。可以把它想象成机场安检把五号电池当危险品没收——流程本身没出错，但拦错了对象；用户感知到的不是安全，而是产品不好用，所以业内也叫它「安全税」。</span>「拒答率」不是越权度量，因为拒答的分母混着两种政策上相反的行为：真拒绝（政策要求）与越权拒绝（政策允许却拒）。只报总拒答率，安全团队与产品团队会各拿一个数打架——前者看到安全，后者看到流失。第二条缺口是投诉流的滞后与偏倚：越权拒绝的真实受害者大多沉默，投诉只代表极小且偏斜的尾部。第三条缺口是判分粒度：答了但全是安全说教、空洞劝诫的输出，若算「完成」，越权率被系统性低估；若算「拒绝」，又把正常带提醒的回答错杀。度量协议要把这三种结果分开计数。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="探针、判分与分域" tabindex="-1">探针、判分与分域 <a class="header-anchor" href="#探针、判分与分域" aria-label="Permalink to &quot;探针、判分与分域&quot;">​</a></h3><p>探针即对照集：表面敏感、政策允许的请求，与危害集同词根反标签，覆盖产品真实流量里越权投诉最集中的域——安全研究、新闻、医疗科普、虚构写作。判分三分：拒答 / 说教化空洞回答 / 完整完成，「说教」计未完成，与上一课的可用性口径相接。数字分域报：总体越权率 \\(r_{\\mathrm{or}}\\) 掩盖的恰是产品最在意的局部。多轮场景里，首轮允许、同一话题追问被突然拒，也计入越权——用户体验与单轮拒绝相同。多语言分层，英语探针的低越权率不担保其他语言。</p>',8)),(e(),A(B,null,{default:a(()=>[i(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20POL%5B%22%E6%94%BF%E7%AD%96%E7%89%88%E6%9C%AC%E5%86%BB%E7%BB%93%22%5D%20--%3E%20PROBE%5B%22%E5%AF%B9%E7%85%A7%E9%9B%86%EF%BC%9A%E5%90%8C%E8%AF%8D%E5%8F%8D%E6%A0%87%E7%AD%BE%20%C3%97%20%E7%9C%9F%E5%AE%9E%E5%9F%9F%22%5D%0A%20%20PROBE%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%EF%BC%9A%E4%B8%8E%E5%AE%89%E5%85%A8%E8%AF%84%E6%B5%8B%E5%90%8C%E4%B8%80%E8%A7%A3%E7%A0%81%E9%85%8D%E7%BD%AE%22%5D%0A%20%20GEN%20--%3E%20JUDGE%5B%22%E4%B8%89%E5%88%86%E8%A3%81%E5%88%A4%EF%BC%9A%E6%8B%92%20%2F%20%E8%AF%B4%E6%95%99%20%2F%20%E5%AE%8C%E6%88%90%22%5D%0A%20%20JUDGE%20--%3E%20STRAT%5B%22%E5%88%86%E5%9F%9F%E8%B6%8A%E6%9D%83%E7%8E%87%22%5D%0A%20%20STRAT%20--%3E%20PAR%5B%22%E5%B8%95%E7%B4%AF%E6%89%98%EF%BC%9A%E8%B6%8A%E6%9D%83%E7%8E%87%20vs%20%E9%85%8D%E5%90%88%E7%8E%87%22%5D%0A%20%20PAR%20--%3E%20WP%5B%22%E5%B7%A5%E4%BD%9C%E7%82%B9%E4%B8%8E%E9%97%A8%E7%A6%81%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>句式检测在机制上必败：越权拒绝的高发形态不是干净的一句「无法协助」，而是长道歉之后接实质性拒绝，或答非所问地绕开请求；反过来，正常回答也常带合规提醒。<span class="marginnote">常见误区：初学者容易以为写几条正则匹配「无法协助」「我不能提供」就能算出越权率。实际上越权拒绝常伪装成一段道歉加转移话题，而正常回答里也满是这类安全句式——句式匹配在两个方向上都大量误判，所以只能靠「请求是否被实质完成」的裁判来切分。</span>只有裁判判「请求是否被实质完成」才切得开。裁判本身要人工校准：抽检一致性不达标的裁判，给出的越权率没有意义。</p><p>帕累托为什么是主图：越权率与危害集配合率通常反相关，单点最优化任何一侧都会把另一侧推向产品不可接受的位置。<span class="marginnote">产品账给越权率定锚：日均一千万次无害请求、2% 的越权率，是每天二十万次失败体验；投诉率若只有 0.1%，工单里只见两千条——用投诉反推越权，会低估两个数量级。</span></p><p>逐层消融延续机制课的结论：生成器、输入门、输出门（见<a href="/llm/output-filter">输出过滤</a>）各自贡献一部分误拦，全开时近似相乘。<span class="marginnote">数字实例：假设生成器、输入门、输出门各自独立误拦 2% 的无害请求，三层全开就是 \\(1 - 0.98^3 \\approx 5.9\\%\\)——接近任何单层的三倍。这就是「叠层相乘」：每一层单独看都还算安全，叠在一起产品已经不可用了，所以降越权前必须先消融，找出最紧的那一层。</span>要降越权，先消融定位是哪一层的阈值在紧，劳动才花得对。</p>',4)),(e(),A(B,null,{default:a(()=>[i(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20REQ%5B%22%E6%97%A0%E5%AE%B3%E8%AF%B7%E6%B1%82%E8%BF%9B%E5%85%A5%22%5D%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E5%99%A8%3Cbr%2F%3E%E8%87%AA%E6%88%91%E5%AE%A1%E6%9F%A5%22%5D%0A%20%20GEN%20--%3E%20G1%5B%22%E8%BE%93%E5%85%A5%E9%97%A8%3Cbr%2F%3E%E5%AE%89%E5%85%A8%E5%88%86%E7%B1%BB%E5%99%A8%22%5D%0A%20%20G1%20--%3E%20G2%5B%22%E8%BE%93%E5%87%BA%E9%97%A8%3Cbr%2F%3E%E8%BE%93%E5%87%BA%E8%BF%87%E6%BB%A4%22%5D%0A%20%20G2%20--%3E%20OK%5B%22%E5%AE%8C%E6%88%90%E5%9B%9E%E7%AD%94%22%5D%0A%20%20GEN%20-.-%3E%7C%E8%AF%AF%E6%8B%A6%7C%20FAIL%5B%22%E8%B6%8A%E6%9D%83%E6%8B%92%E7%BB%9D%22%5D%0A%20%20G1%20-.-%3E%7C%E8%AF%AF%E6%8B%A6%7C%20FAIL%0A%20%20G2%20-.-%3E%7C%E8%AF%AF%E6%8B%A6%7C%20FAIL%0A%20%20FAIL%20--%3E%20ABL%5B%22%E9%80%90%E5%B1%82%E5%85%B3%E6%96%AD%E6%B6%88%E8%9E%8D%3Cbr%2F%3E%E5%AE%9A%E4%BD%8D%E6%9C%80%E7%B4%A7%E7%9A%84%E4%B8%80%E5%B1%82%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>政策更新是重标事件而非退步事件：新禁一类意图会把原对照题变成真拒绝，越权率必须在新政策版本下重测。拒答带内部原因码（仅服务端），越权样本才能回流进对照桶改造探针。越权会伪装成诚实——「我不确定，所以不能说」既逃立场又逃请求，见<a href="/llm/honesty-citations">引用与诚实</a>的边界；对照集里要含模型应当能答的题，别把无知模板算成无害。最后，不要用「用户没再问」当越权下降的证据：用户可能只是走了。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>越权拒绝与真拒绝共用「拒答」外壳，度量必须在政策允许集上单独构造。</li><li>判分三分：拒答、说教化未完成、完整完成；把说教算完成会低估越权。</li><li>主图是帕累托：越权率与危害配合率成对报，单侧最优必翻车。</li><li>分域、多轮、多语言分层；总体的一个数是产品最用不上的数。</li><li>逐层消融定位误拦来源；投诉流低估越权两个数量级，不能当主指标。</li><li>出处：Bai et al., 2022；XSTest 等公开过拒绝探针的官方口径；本课程协议整理。</li></ul>',4))])}const u=o(d,[["render",m]]);export{f as __pageData,u as default};
